(29461, 'Acts 6:1', 'Acts', 6, 1, 'په هغو ورځو کې چې د عیسی د پیروانو شمېر زیاتېده، نو یوناني ژبو یهودیانو د عبراني ژبو یهودیانو څخه شکایت وکړ چې د ورځني خوراک د وېشلو په وخت کې یوناني ژبو یهودي کونډو ښځو ته خپله برخه نه ورکول کیږي.', 'په هغو ورجو کې چې د عیسی د پیروانو شمېر زیاتېده، نو یونانی ژبو یهودیانو د عبرانی ژبو یهودیانو چخه شکایت وکر چې د ورجنی خوراک د وېشلو په وخت کې یونانی ژبو یهودی کوندو شجو ته خپله برخه نه ورکول کیزی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29462, 'Acts 6:2', 'Acts', 6, 2, 'نو هغو دولسو رسولانو ټول ایمانداران راوغوښتل او ویې ویل: «دا زمونږ دپاره مناسبه نه ده چې نورو ته د خوړو د رسولو په خاطر خلکو ته د خدای د پیغام رسول پرېږدو.', 'نو هغو دولسو رسولانو تول ایمانداران راوغوشتل او ویې ویل: «دا زمونز دپاره مناسبه نه ده چې نورو ته د خورو د رسولو په خاطر خلکو ته د خدای د پیغام رسول پرېزدو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29463, 'Acts 6:3', 'Acts', 6, 3, 'نو ای خویندو او ورونو! د خپل منځ څخه اووه تنه چې نېک نامه او د روح القدس څخه ډک او د حکمت لرونکي خلک وي غوره کړئ، ترڅو د دې کارونو مسوولیت د هغوی په غاړه واچوو.', 'نو ای خویندو او ورونو! د خپل منج چخه اووه تنه چې نېک نامه او د روح القدس چخه دک او د حکمت لرونکی خلک وی غوره کری، ترچو د دې کارونو مسوولیت د هغوی په غاره واچوو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29464, 'Acts 6:4', 'Acts', 6, 4, 'خو مونږ به خپل وخت په دعا کولو او د خدای د کلام په وعظ او تعلیم ورکولو تېروو.»', 'خو مونز به خپل وخت په دعا کولو او د خدای د کلام په وعظ او تعلیم ورکولو تېروو.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29465, 'Acts 6:5', 'Acts', 6, 5, 'د رسولانو دا نظر د ټولو خوښ شو، نو هغوی استیفان چې ډېر ایمانداره سړی ؤ او د روح القدس څخه ډک ؤ او فیلیپوس، پروکروس، نیکانور، تیمون، پرمیناس او نیکولاوس چې یهودي شوی ؤ او د سوریې د انطاکیې څخه ؤ، غوره کړل.', 'د رسولانو دا نظر د تولو خوش شو، نو هغوی استیفان چې دېر ایمانداره سری و او د روح القدس چخه دک و او فیلیپوس، پروکروس، نیکانور، تیمون، پرمیناس او نیکولاوس چې یهودی شوی و او د سوریې د انطاکیې چخه و، غوره کرل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29466, 'Acts 6:6', 'Acts', 6, 6, 'هغوی دا کسان رسولانو ته وروپېژندل او رسولانو د هغوی په سرونو باندې خپل لاسونه کېښودل او د هغوی دپاره یې دعا وکړه.', 'هغوی دا کسان رسولانو ته وروپېژندل او رسولانو د هغوی په سرونو باندې خپل لاسونه کېشودل او د هغوی دپاره یې دعا وکره.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29467, 'Acts 6:7', 'Acts', 6, 7, 'نو د خدای کلام په پرله پسې توګه خپرېده او په اورشلیم کې د ایماندارانو شمېر زیاتېده او ډېرو کاهنانو هم ایمان راوړ. د استیفان نیول', 'نو د خدای کلام په پرله پسې توګه خپرېده او په اورشلیم کې د ایماندارانو شمېر زیاتېده او دېرو کاهنانو هم ایمان راور. د استیفان نیول', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29468, 'Acts 6:8', 'Acts', 6, 8, 'استیفان چې د خدای د فضل او قدرت څخه ډک ؤ، د خلکو په منځ کې به یې ډېر حیرانوونکي کارونه کول او معجزې به یې ښودلې.', 'استیفان چې د خدای د فضل او قدرت چخه دک و، د خلکو په منج کې به یې دېر حیرانوونکی کارونه کول او معجزې به یې شودلې.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29469, 'Acts 6:9', 'Acts', 6, 9, 'خو ځینې خلک چې د ازادو خلکو په نوم د کنیسې غړي وو چې د قیروان او سکندریې د ښارونو او نور خلک چې د قیلیقیې او اسیا د ولایتونو څخه وو، راپورته شول او د استیفان سره یې بحث پیل کړ.', 'خو جینې خلک چې د ازادو خلکو په نوم د کنیسې غری وو چې د قیروان او سکندریې د شارونو او نور خلک چې د قیلیقیې او اسیا د ولایتونو چخه وو، راپورته شول او د استیفان سره یې بحث پیل کر.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(29470, 'Acts 6:10', 'Acts', 6, 10, 'خو استیفان داسې په حکمت او د روح القدس په قدرت سره خبرې کولې چې هغوی نه شو کولای د هغه په وړاندې ودریږي.', 'خو استیفان داسې په حکمت او د روح القدس په قدرت سره خبرې کولې چې هغوی نه شو کولای د هغه په وراندې ودریزی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
